import{a as e,i as t,n,r,t as i}from"./kit-KASxg-TP.js";function a(a){let o=e({label:`workers`,min:2,max:8,value:4,onInput:h}),s=e({label:`skew (slow data)`,min:0,max:10,value:6,fmt:e=>e+`/10`,onInput:h}),c=n(`New data`,()=>{l=(l*7+3)%1e3,h()}),l=11,{cv:u,ctx:d,w:f,h:p}=r(720,250),m=t(`div`,{class:`out`});function h(){let e=o.get(),t=s.get()/10,n=l,r=()=>(n=n*1103515245+12345&2147483647)/2147483647,a=Array.from({length:96},(e,n)=>1+(n<24?t*6:0)+r()*.5),c=96/e,u=Array.from({length:e},(e,t)=>{let n=0;for(let e=Math.floor(t*c);e<Math.floor((t+1)*c);e++)n+=a[e];return n}),h=Array(e).fill(0),g=Array.from({length:e},()=>[]);a.forEach((t,n)=>{let r=0;for(let t=1;t<e;t++)h[t]<h[r]&&(r=t);g[r].push([h[r],h[r]+t,n]),h[r]+=t});let _=Math.max(...h),v=Math.max(...u),y=a.reduce((e,t)=>e+t,0);d.clearRect(0,0,f,p),d.font=`11px monospace`;let b=600/Math.max(_,v);d.fillStyle=i.dim,d.fillText(`static partitioning`,8,12),u.forEach((e,t)=>{let n=18+t*12;d.fillStyle=i.bad,d.fillRect(90,n,e*b,9)});let x=28+e*12;d.fillStyle=i.dim,d.fillText(`morsel-driven`,8,x),g.forEach((e,t)=>e.forEach(([e,n,r])=>{d.fillStyle=r%2?i.good:`#6a9a45`,d.fillRect(90+e*b,x+6+t*12,Math.max(.5,(n-e)*b),9)})),d.strokeStyle=i.warn,d.beginPath(),d.moveTo(90+v*b,14),d.lineTo(90+v*b,x+6+e*12),d.stroke(),m.innerHTML=`ideal (total/workers) = ${(y/e).toFixed(1)}   static finish = <b class="bad">${v.toFixed(1)}</b> (${(v/(y/e)).toFixed(2)}x ideal)   morsel finish = <b class="good">${_.toFixed(1)}</b> (${(_/(y/e)).toFixed(2)}x ideal)\nStatic ranges leave workers idle waiting for the slowest one. With ~100K-tuple morsels pulled from a shared dispatcher, the tail is at most one morsel.`}a.append(t(`div`,{class:`row`},o.el,s.el,c),u,m),h()}var o={n:6,title:`Scheduling & parallelism`,minutes:14,cmu:`CMU 15-445 L14, 15-721 L4 (Parallel execution)`,components:[`scheduler`,`parallelism`,`exchange-shuffle`],goals:[`Distinguish inter-query, intra-query (inter-operator, intra-operator) parallelism.`,`Explain morsel-driven scheduling and why it handles skew and NUMA better than exchange-based plans.`,`Compare thread-per-connection, thread pool, and thread-per-core (shared-nothing per core).`],body:`
<h2>Kinds of parallelism</h2>
<ul><li><b>Inter-query</b>: different queries on different threads. The OLTP default; needs concurrency control and latches.</li>
<li><b>Intra-query, inter-operator (pipeline)</b>: different operators run concurrently, passing data (producer/consumer).</li>
<li><b>Intra-operator (data parallel)</b>: split one operator's input into partitions and run the same operator on each. Parallel scan, partitioned hash join, parallel aggregation (local then global merge).</li></ul>
<h2>Exchange-based vs morsel-driven</h2>
<p>The classic Volcano <b>exchange operator</b> inserts parallelism into a plan statically: the optimizer fixes a degree of parallelism and partitions data up front. If one partition is bigger or its thread gets descheduled, the query waits on the straggler.</p>
<p><b>Morsel-driven parallelism</b> (Leis et al., SIGMOD 2014, HyPer) keeps a fixed pool of worker threads, one per hardware thread. Input is cut into <b>morsels</b> of about 100,000 tuples. A dispatcher hands a free worker the next morsel of the currently running pipeline, preferring morsels whose memory is on the worker's NUMA node. The degree of parallelism can change mid-query (when a higher priority query arrives), and skew is absorbed because fast workers simply take more morsels. DuckDB, Umbra, Velox-based engines and Snowflake-like systems use variants.</p>
<div data-demo="0"></div>
<h2>Thread models for connections</h2>
<table><tr><th>Model</th><th>How</th><th>Pros</th><th>Cons</th></tr>
<tr><td>Process/thread per connection</td><td>PostgreSQL process per connection; MySQL thread per connection</td><td>Simple isolation; blocking I/O is easy</td><td>10K connections = 10K stacks, context switches; needs a pooler (PgBouncer)</td></tr>
<tr><td>Thread pool</td><td>fixed workers service a request queue (MySQL thread pool plugin)</td><td>Bounded concurrency</td><td>Long queries starve short ones; blocking inside a worker wastes it</td></tr>
<tr><td>Morsel-driven pool</td><td>one worker per core, tasks = morsels</td><td>Elastic, skew-tolerant, NUMA aware</td><td>Needs cooperative operators and a task scheduler</td></tr>
<tr><td>Thread-per-core (shared-nothing)</td><td>ScyllaDB/Seastar, TigerBeetle single thread; each core owns a data shard</td><td>No locks or latches, predictable latency, cache locality</td><td>Cross-shard requests need message passing; hot shard bottleneck</td></tr></table>
<div class="callout ripple"><div class="t">Scheduling shapes everything else</div><p>Thread-per-core removes the need for latches on data structures (one writer per shard) but forces data partitioning and a routing layer inside the process; the same logic as sharding across machines, applied to cores.</p></div>
<h2>Interaction with I/O</h2>
<p>With async I/O (io_uring, Seastar) a core never blocks; it switches to another task while a read is in flight. With blocking buffer-pool reads a thread-pool engine needs many more threads than cores to hide I/O latency, which then raises context-switch overhead.</p>`,demos:[{title:`Static partitions vs morsels`,caption:`Make a quarter of the data expensive and compare finish times.`,mount:a}],tradeoffs:{head:[`Design`,`Skew handling`,`Contention`,`Best for`],rows:[[`Static partition / exchange`,`Poor`,`Low (private partitions)`,`Distributed shuffles, simple plans`],[`Morsel-driven work stealing`,`Excellent`,`Shared dispatcher, small`,`Single-node analytics, NUMA`],[`Thread-per-core`,`Hot shard problem`,`None inside a shard`,`Low-latency KV/OLTP (Scylla, TigerBeetle)`],[`Thread per connection`,`n/a`,`High (latches, context switches)`,`Moderate concurrency OLTP`]]},ripples:[{to:`Latches / concurrency`,text:`more threads touching shared structures means more latch contention; thread-per-core removes it.`},{to:`Buffer pool`,text:`a shared buffer pool is a contention point; per-core caches or partitioned pools help.`},{to:`Operators`,text:`aggregation and joins need thread-local state merged at the end, shaping hash table design.`},{to:`Storage`,text:`parallel scans want data in many files or row groups so morsels map to independent units.`}],quiz:[{q:`Why does morsel-driven scheduling tolerate skew?`,options:[`It sorts the data first`,`Workers pull small units on demand, so fast workers do more`,`It uses more threads than cores`],answer:1,why:`Dynamic assignment removes the straggler effect of static ranges.`},{q:`What is the main cost of thread-per-core designs?`,options:[`More locks`,`Cross-shard work needs messaging and hot shards cannot be shared`,`Slower disks`],answer:1,why:`Each core owns its data, so cross-core access is explicit message passing.`},{q:`Intra-operator parallelism means…`,options:[`Many queries at once`,`Splitting one operator across threads/partitions`,`Pipelining two operators`],answer:1,why:`Same operator, different data partitions.`}],refs:[{title:`Leis et al., Morsel-Driven Parallelism (SIGMOD 2014)`,url:`https://db.in.tum.de/~leis/papers/morsels.pdf`},{title:`Seastar shared-nothing design`,url:`https://seastar.io/shared-nothing/`},{title:`CMU 15-721 schedule`,url:`https://15721.courses.cs.cmu.edu/spring2024/schedule.html`},{title:`Graefe, Encapsulation of Parallelism in the Volcano System (1990)`,url:`https://dl.acm.org/doi/10.1145/93597.98720`}]};export{o as default};